<?php
$editing = in_array($action, ['add', 'edit'], true);
$title = $action === 'add' ? 'Write an article' : ($action === 'edit' ? 'Edit article' : ($action === 'delete' ? 'Delete article' : 'Publishing'));
blog_head($title, 'Private Bed Mesh publishing tools.', true, null, $editing ? ['/css/editor.css'] : []);
?>
<main class="blog-shell blog-admin-shell" id="blog-main"><?php blog_admin_navigation('posts'); ?><header class="blog-admin-header"><div><p class="blog-eyebrow">The Bed Mesh journal</p><h1><?= esc($title) ?></h1></div><?php if ($action === 'view'): ?><a class="button" href="<?= esc(blog_url('admin/posts/add')) ?>">Write an article <span aria-hidden="true">＋</span></a><?php else: ?><a href="<?= esc(blog_url('admin')) ?>">← All articles</a><?php endif; ?></header>
<?php if ($flash): ?><p class="blog-notice" role="status"><?= esc($flash) ?></p><?php endif; ?>
<?php if ($errors): ?><div class="blog-notice blog-notice--error" role="alert"><strong>Check the fields below.</strong><?php foreach ($errors as $error): ?><p><?= esc($error) ?></p><?php endforeach; ?></div><?php endif; ?>
<?php if ($action === 'delete'): ?>
<section class="blog-confirm"><h2><?= esc($record['title']) ?></h2><p>Deleting this article removes its draft and public page. This cannot be undone. Uploaded files are retained because other articles may use them.</p><form method="post"><?= csrf_field() ?><div class="blog-actions"><button type="submit" class="button blog-danger">Delete article</button><a href="<?= esc(blog_url('admin/posts/edit/' . $id)) ?>">Keep article</a></div></form></section>
<?php elseif ($editing): ?>
<form method="post" enctype="multipart/form-data" class="blog-editor-form" data-recovery-url="<?= esc(blog_url('admin/recovery/' . (int) ($record['id'] ?? 0))) ?>" data-post-id="<?= (int) ($record['id'] ?? 0) ?>" data-has-unsaved="<?= $errors ? 'true' : 'false' ?>"><?= csrf_field() ?><input type="hidden" name="edit_version" value="<?= (int) ($_POST['edit_version'] ?? $record['edit_version'] ?? 0) ?>"><input type="hidden" name="recovery_version" value="<?= (int) ($_POST['recovery_version'] ?? 0) ?>"><div class="blog-editor-main"><label for="article-title">Article title<input id="article-title" type="text" name="title" required maxlength="100" value="<?= blog_form_value($record, 'title') ?>" placeholder="A clear title for your next idea"></label><label for="article-excerpt">Short summary<span>Optional. Used in the journal and search previews.</span><textarea id="article-excerpt" name="excerpt" maxlength="300" rows="3"><?= blog_form_value($record, 'excerpt') ?></textarea></label><label for="article-content">Article body<span>Use the formatting controls to insert paragraphs, headings, lists, links, and code, or edit the HTML directly. Save a draft to check its private preview.</span><textarea id="article-content" data-editor name="content" required rows="24" class="blog-code-input" spellcheck="true" placeholder="&lt;p&gt;Start with your observation…&lt;/p&gt;&#10;&#10;&lt;h2&gt;What it means&lt;/h2&gt;"><?= blog_form_value($record, 'content') ?></textarea></label><details class="blog-editor-help"><summary>A quick formatting reference</summary><pre><code>&lt;h2&gt;Section heading&lt;/h2&gt;
&lt;p&gt;A paragraph with &lt;strong&gt;emphasis&lt;/strong&gt;.&lt;/p&gt;
&lt;ul&gt;&lt;li&gt;An observation&lt;/li&gt;&lt;/ul&gt;
&lt;a href="https://example.com"&gt;A useful source&lt;/a&gt;
&lt;pre&gt;&lt;code&gt;A small code example&lt;/code&gt;&lt;/pre&gt;</code></pre><p>Save a draft, then open its private preview to check the article layout.</p></details></div><aside class="blog-editor-settings"><h2>Publication</h2><label for="article-status">Status<select id="article-status" name="status"><option value="draft"<?= ($_POST['status'] ?? $record['status'] ?? 'draft') === 'draft' ? ' selected' : '' ?>>Draft — private</option><option value="published"<?= ($_POST['status'] ?? $record['status'] ?? '') === 'published' ? ' selected' : '' ?>>Published — public</option></select></label><label for="article-category">Category<select id="article-category" name="category_id" required><option value="">Choose a category</option><?php foreach ($categories as $item): ?><option value="<?= (int) $item['id'] ?>"<?= (string) ($_POST['category_id'] ?? $record['category_id'] ?? '') === (string) $item['id'] ? ' selected' : '' ?><?= $item['disabled'] ? ' disabled' : '' ?>><?= esc($item['category']) ?><?= $item['disabled'] ? ' (hidden)' : '' ?></option><?php endforeach; ?></select></label><a class="blog-small-link" href="<?= esc(blog_url('admin/categories')) ?>">Manage categories →</a><?php $currentImage = blog_article_image($record['image'] ?? null); $assetChoices = blog_article_asset_choices(); ?>
<label for="article-image">Featured image<span>A relevant image is required for publishing. Drafts can be saved without one. JPEG, PNG, or WebP, up to 5 MB.</span><input id="article-image" name="image" type="file" accept="image/jpeg,image/png,image/webp"></label>
<?php if ($assetChoices): ?><label for="article-existing-image">Or use a site image<select id="article-existing-image" name="existing_image"><option value="">Keep the current image</option><?php foreach ($assetChoices as $asset): ?><option value="<?= esc($asset) ?>"<?= ($_POST['existing_image'] ?? '') === $asset ? ' selected' : '' ?>><?= esc(pathinfo($asset, PATHINFO_FILENAME)) ?></option><?php endforeach; ?></select></label><?php endif; ?>
<?php if ($currentImage): ?><img class="blog-admin-image" src="<?= esc($currentImage['url']) ?>" alt="<?= esc($record['image_alt'] ?: 'Current featured image') ?>"><label class="blog-check"><input type="checkbox" name="remove_image" value="1"<?= ($_POST['remove_image'] ?? '') === '1' ? ' checked' : '' ?>> Remove featured image</label><?php endif; ?>
<label for="article-image-alt">Image description<span>Required when using an image. Describe the detail relevant to this article.</span><textarea id="article-image-alt" name="image_alt" maxlength="250" rows="3"><?= blog_form_value($record, 'image_alt') ?></textarea></label>
<label for="article-image-caption">Caption<span>Optional context shown below the image.</span><textarea id="article-image-caption" name="image_caption" maxlength="500" rows="3"><?= blog_form_value($record, 'image_caption') ?></textarea></label>
<label for="article-image-credit">Image credit<input id="article-image-credit" name="image_credit" type="text" maxlength="150" value="<?= blog_form_value($record, 'image_credit') ?>" placeholder="e.g. Screenshot: Bed Mesh"></label>
<label for="article-image-credit-url">Credit link<span>Optional complete http or https URL.</span><input id="article-image-credit-url" name="image_credit_url" type="url" maxlength="500" value="<?= blog_form_value($record, 'image_credit_url') ?>"></label>
<button class="button" type="submit">Save article</button><?php if ($record): ?><a class="button button-secondary" href="<?= esc(blog_url('post/' . $record['slug'], ['preview' => 1])) ?>">Open private preview ↗</a><?php if ($record['status'] === 'published'): ?><a class="blog-small-link" href="<?= esc(blog_url('post/' . $record['slug'])) ?>">View published article ↗</a><?php endif; ?><p class="blog-editor-note">URL: <code>post/<?= esc($record['slug']) ?></code><br>The URL stays the same when you edit the title.</p><a class="blog-small-link" href="<?= esc(blog_url('admin/revisions/' . $id)) ?>">Saved revision history →</a><a class="blog-delete-link" href="<?= esc(blog_url('admin/posts/delete/' . $id)) ?>">Delete article</a><?php else: ?><p class="blog-editor-note">A public URL is created on the first save. Drafts are visible only to signed-in administrators.</p><?php endif; ?></aside></form>
<?php else: ?>
<form class="blog-admin-filter" method="get"><label for="publishing-find" class="screen-reader-text">Find articles</label><input id="publishing-find" type="search" name="find" value="<?= esc($search) ?>" placeholder="Find an article…"><label for="publishing-status" class="screen-reader-text">Publication status</label><select id="publishing-status" name="status"><option value="">All statuses</option><option value="draft"<?= $filter === 'draft' ? ' selected' : '' ?>>Drafts</option><option value="published"<?= $filter === 'published' ? ' selected' : '' ?>>Published</option></select><button class="button button-secondary" type="submit">Filter</button></form>
<div class="blog-admin-table-wrap"><table class="blog-admin-table"><thead><tr><th scope="col">Article</th><th scope="col">Status</th><th scope="col">Updated</th><th scope="col">Actions</th></tr></thead><tbody><?php foreach ($posts as $item): ?><tr><th scope="row"><a href="<?= esc(blog_url('admin/posts/edit/' . $item['id'])) ?>"><?= esc($item['title']) ?></a><small><?= esc($item['category'] ?: 'No category') ?></small></th><td><span class="blog-status blog-status--<?= $item['status'] === 'published' ? 'published' : 'draft' ?>"><?= $item['status'] === 'published' ? 'Published' : 'Draft' ?></span></td><td><?= esc(blog_date($item['updated_at'] ?: $item['date'])) ?></td><td><a href="<?= esc(blog_url('admin/posts/edit/' . $item['id'])) ?>">Edit</a><a href="<?= esc(blog_url('post/' . $item['slug'], ['preview' => 1])) ?>">Preview</a></td></tr><?php endforeach; ?></tbody></table><?php if (!$posts): ?><p class="blog-table-empty">No articles here yet. Write the first one when you have an idea to share.</p><?php endif; ?></div><?php blog_pagination($pageNumber, $pages, 'admin', array_filter(['status' => $filter, 'find' => $search], static fn ($value) => $value !== '')); ?>
<?php endif; ?></main><?php if ($editing): ?><script type="module" src="<?= esc(site_asset_url('/js/blog-editor.js')) ?>"></script><?php endif; ?><?php blog_foot(); ?>
